/* availWeekdays : jours de la semaine où le prestataire est dispo
   (0=dimanche … 6=samedi). booked : jours du mois déjà réservés (exemple). */
/* Prestataires : catalogue vide au lancement (03/09/2026) — aucun profil fictif.
   Format d'une fiche : {id, n (nom), c (slug catégorie), sub (slug sous-catégorie), t (titre court), city, zone,
   price ('Dès 350 €' / 'Sur devis'), r (note 1-5), rev (nb avis), badge ('' | 'Premium' | 'Vedette'),
   bio, services:[{name,price}], availWeekdays:[0-6], booked:[jours du mois]} */
window.CELEOR_DATA = [
];

/* Helpers partagés (catalogue, fiches, assistant) */
window.CELEOR_SUBS = [].concat.apply([], window.CELEOR_CATS.map(function(c){
  return c.subs.map(function(s){ return {slug:s.slug, label:s.label, cat:c.slug, catLabel:c.label}; });
}));
window.celeorCat = function(slug){ return window.CELEOR_CATS.find(function(c){ return c.slug===slug; }); };
window.celeorSub = function(slug){ return window.CELEOR_SUBS.find(function(s){ return s.slug===slug; }); };

